class PlayerScreen extends StatefulWidget { final Channel ch; const PlayerScreen({super.key,required this.ch}); @override State<PlayerScreen> createState()=>_S(); }
class _S extends State<PlayerScreen>{VideoPlayerController? controller; String? error; bool busy=true,controls=true; @override void initState(){super.initState();_start();} Future<void> _start() async {if(!mounted)return;setState((){busy=true;error=null;});try{var url=widget.ch.url;Map<String,String> headers={};if(widget.ch.cmd!=null){final source=Store.sources().firstWhere((s)=>s.id==widget.ch.sourceId);final st=Stalker(source);await st.connect();url=await st.link(widget.ch.cmd!);headers=st.headers;}final next=VideoPlayerController.networkUrl(Uri.parse(url),httpHeaders:headers);await next.initialize().timeout(const Duration(seconds:45));await next.play();if(!mounted){await next.dispose();return;}final old=controller;setState((){controller=next;busy=false;});await old?.dispose();}catch(e){if(mounted)setState((){error='تعذر تشغيل القناة. تحقق من الرابط أو صلاحية الاشتراك.\n$e';busy=false;});}} @override void dispose(){controller?.dispose();WakelockPlus.disable();SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);super.dispose();} Future<void> _fullscreen() async {final full=!controls;setState(()=>controls=!controls);await SystemChrome.setEnabledSystemUIMode(full?SystemUiMode.immersiveSticky:SystemUiMode.edgeToEdge);await SystemChrome.setPreferredOrientations(full?[DeviceOrientation.landscapeLeft,DeviceOrientation.landscapeRight]:DeviceOrientation.values);if(full){await WakelockPlus.enable();}else{await WakelockPlus.disable();}} @override Widget build(BuildContext context){final c=controller;return Scaffold(backgroundColor:Colors.black,appBar:controls?AppBar(title:Text(widget.ch.name),actions:[IconButton(icon:Icon(Store.isFav(widget.ch)?Icons.favorite:Icons.favorite_border),onPressed:()async{await Store.toggleFav(widget.ch);if(mounted)setState((){});})]):null,body:Center(child:busy?const CircularProgressIndicator():error!=null?Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(error!,textAlign:TextAlign.center),const SizedBox(height:16),FilledButton(onPressed:_start,child:const Text('إعادة المحاولة'))])):GestureDetector(onTap:()async{if(c==null)return;setState((){});c.value.isPlaying?await c.pause():await c.play();},child:Stack(alignment:Alignment.center,children:[AspectRatio(aspectRatio:c!.value.aspectRatio,child:VideoPlayer(c)),if(controls)Positioned(bottom:18,right:18,child:IconButton.filled(onPressed:_fullscreen,icon:const Icon(Icons.fullscreen,size:30))),if(!c.value.isPlaying)const Icon(Icons.play_circle_fill,size:64,color:Colors.white70)]))));}}
